INSERT INTO `perangkat_ajar` VALUES (10,3,'Ganjil',7,1,34,'Modul Ajar','E','','','Peserta didik mampu memahami hakikat ilmu kimia dan perannya dalam kehidupan, menerapkan metode ilmiah serta prinsip \r\nkeselamatan kerja di laboratorium, menjelaskan prinsip Kimia Hijau (Green Chemistry) dan kaitannya dengan isu lingkungan, \r\nmenganalisis struktur atom, sistem periodik unsur, dan ikatan kimia untuk menjelaskan sifat materi, serta menerapkan hukum-hukum \r\ndasar kimia dan konsep stoikiometri dalam menyelesaikan berbagai permasalahan kuantitatif reaksi kimia. Peserta didik juga mampu \r\nmenerapkan keterampilan proses sains melalui kegiatan mengamati, mempertanyakan, memprediksi, merencanakan dan melakukan \r\npenyelidikan, mengolah serta menganalisis data, mengevaluasi hasil penyelidikan, dan mengomunikasikan hasilnya secara ilmiah \r\nsesuai prosedur keselamatan kerja laboratorium. ','','','','','','','','2',1,'assets/uploads/perangkat/2026_2027/Ganjil/34/1/PERANGKAT_Modul_Ajar_1_1788699297.pdf','Menunggu Verifikasi',NULL,1,NULL,1,0,4,'2026-09-06 19:54:58',NULL,NULL,NULL);
